import { Injectable } from '@angular/core';
import { HttpClient, HttpErrorResponse, HttpParams } from '@angular/common/http';
import { Observable, throwError } from 'rxjs';
import { catchError, retry } from 'rxjs/operators';
import { environment } from '../../../environments/environment';

import { MOCK_DB } from '../data/mock-db';
import { of } from 'rxjs';

@Injectable({
    providedIn: 'root'
})
export class ApiService {
    private apiUrl = environment.apiUrl;

    constructor(private http: HttpClient) { }

    get<T>(path: string, params: HttpParams = new HttpParams()): Observable<T> {
        if (environment.useMockData) {
            console.log('Mock API GET:', path);
            if (path === 'temples') {
                return of(MOCK_DB.temples as unknown as T);
            }
        }

        return this.http.get<T>(`${this.apiUrl}/${path}`, { params }).pipe(
            retry(1),
            catchError(this.handleError)
        );
    }

    post<T>(path: string, body: any): Observable<T> {
        if (environment.useMockData) {
            console.log('Mock API POST:', path, body);
            if (path === 'bookings') {
                // Simulate successful booking response
                return of({ id: 'MOCK_' + Date.now(), status: 'confirmed', ...body } as unknown as T);
            }
        }

        return this.http.post<T>(`${this.apiUrl}/${path}`, body).pipe(
            catchError(this.handleError)
        );
    }

    put<T>(path: string, body: any): Observable<T> {
        return this.http.put<T>(`${this.apiUrl}/${path}`, body).pipe(
            catchError(this.handleError)
        );
    }

    delete<T>(path: string): Observable<T> {
        return this.http.delete<T>(`${this.apiUrl}/${path}`).pipe(
            catchError(this.handleError)
        );
    }

    private handleError(error: HttpErrorResponse) {
        let errorMessage = 'Unknown error!';
        if (error.error instanceof ErrorEvent) {
            // Client-side errors
            errorMessage = `Error: ${error.error.message}`;
        } else {
            // Server-side errors
            errorMessage = `Error Code: ${error.status}\nMessage: ${error.message}`;
        }
        return throwError(() => new Error(errorMessage));
    }
}
