import { createAction, props } from '@ngrx/store';
import { Booking } from '../../core/models/booking.model';

export const createBooking = createAction(
    '[Booking] Create Booking',
    props<{ booking: Booking }>()
);

export const createBookingSuccess = createAction(
    '[Booking] Create Booking Success',
    props<{ booking: Booking }>()
);

export const createBookingFailure = createAction(
    '[Booking] Create Booking Failure',
    props<{ error: any }>()
);

export const updateBookingDraft = createAction(
    '[Booking] Update Draft',
    props<{ partialBooking: Partial<Booking> }>()
);

export const resetBookingDraft = createAction('[Booking] Reset Draft');
